pub fn deepClone(self: ParsedComponent, allocator: std.mem.Allocator) @This() {
            const s = self;
            return css.implementDeepClone(@This(), (&s), allocator);
    }
    
    pub const This = @This();
};

pub const Multiplier = enum {
    none,
    space,
    comma,
    pub fn get(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn has(__cp_s: []const u8) bool { return std.meta.stringToEnum(@This(), __cp_s) != null; }
    pub fn fromName(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn name(__cp_self: @This()) []const u8 { return @tagName(__cp_self); }
};

pub const SyntaxComponent = struct {
    kind: SyntaxComponentKind,
    multiplier: Multiplier,

pub fn parseString(input: *[]const u8) css.Maybe(SyntaxComponent,void) {
            const kind = (switch (SyntaxComponentKind.parseString(input)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            if ((kind == .transform_list)) {
                return .{ .result = SyntaxComponent{ .kind = kind, .multiplier = .none } };
            }
            var multiplier: Multiplier = .none;
            _ = &multiplier;
            if (bun.strings.startsWithChar(input.*, 43)) {
                input.* = input.*[1..];
                multiplier = .space;
            } else {
                if (bun.strings.startsWithChar(input.*, 35)) {
                    input.* = input.*[1..];
                    multiplier = .comma;
                }
            }
            return .{ .result = SyntaxComponent{ .kind = kind, .multiplier = multiplier } };
    }

pub fn toCss(self: SyntaxComponent, dest: *Printer) PrintErr!void {
            _ = try self.kind.toCss(dest);
            return (switch (self.multiplier) {
.none => {
{
            }
},
.comma => dest.writeChar(35),
.space => dest.writeChar(43),
});
    }

pub fn deepClone(self: SyntaxComponent, allocator: std.mem.Allocator) @This() {
            const s = self;
            return css.implementDeepClone(@This(), (&s), allocator);
    }
};

