pub fn isIdentStart(c: u8) bool {
        return (((((c >= 65) and (c <= 90)) or ((c >= 97) and (c <= 122))) or (c >= 128)) or (c == 95));
}

pub fn isNameCodePoint(c: u8) bool {
        return ((isIdentStart(c) or ((c >= 48) and (c <= 57))) or (c == 45));
}
